<template><label class="vs-switch"><input :checked="modelValue" type="checkbox" role="switch" :disabled="disabled" @change="$emit('update:modelValue',$event.target.checked)"/><span class="vs-switch__track" aria-hidden="true"><i></i></span><span><strong>{{label}}</strong><small v-if="description">{{description}}</small></span></label></template>
<script setup>defineProps({modelValue:Boolean,label:{type:String,required:true},description:{type:String,default:''},disabled:Boolean});defineEmits(['update:modelValue'])</script>
<style scoped>.vs-switch{display:inline-flex;align-items:flex-start;gap:var(--space-3);min-height:44px;cursor:pointer}.vs-switch input{position:absolute;opacity:0}.vs-switch__track{width:42px;height:24px;padding:3px;border:1px solid var(--border-strong);border-radius:var(--radius-pill);background:var(--surface-subtle);transition:background .18s}.vs-switch__track i{display:block;width:16px;height:16px;border-radius:50%;background:var(--text-muted);transition:transform .18s}.vs-switch input:checked+.vs-switch__track{background:var(--interactive-primary);border-color:var(--interactive-primary)}.vs-switch input:checked+.vs-switch__track i{transform:translateX(18px);background:var(--text-on-interactive)}.vs-switch input:focus-visible+.vs-switch__track{outline:3px solid color-mix(in srgb,var(--border-focus) 35%,transparent);outline-offset:2px}.vs-switch strong,.vs-switch small{display:block}.vs-switch small{color:var(--text-muted);font-size:var(--type-caption-size)}</style>
